"""C1/C2 prompt-cache stability on Anthropic: multi-turn sessions, paired arms (scratch experiment driver).

Strata: "sat" seeds 24 completed short exchanges (no provider) and then runs real turns, arms base vs hyst;
"mem" runs real turns from an empty history with 10 memories, one of which changes at turn 6, arms base vs stable.
Every turn asks for one task to be created (deterministic effect check); the last turn asks about a task created
three turns earlier (literal title in the reply).
"""
import argparse, concurrent.futures, contextvars, dataclasses, json, random, secrets, sys, threading, time
from pathlib import Path
import agent_runtime, context_budget, turn_prompt, memory as team_memory, provider_client
from eval import cost as eval_cost, stats as eval_stats, injection
from eval.ceiling import Ceiling
from eval.intent_route import _key
from langchain_core.messages import AIMessage, HumanMessage
from langgraph.checkpoint.memory import InMemorySaver
import model_usage

ARM = contextvars.ContextVar("arm", default="base")
CTX = contextvars.ContextVar("ctx", default=None)
SEEDING = contextvars.ContextVar("seeding", default=False)
PROVIDER = contextvars.ContextVar("provider", default="openai")
LOW_EXCHANGES, LOW_TOKENS = 16, 96_000
CACHE = {"type": "ephemeral", "ttl": "5m"}
TASKS = injection.ASSISTANTS["tasks"]
WORDS = ("amber", "birch", "cobalt", "delta", "ember", "fjord", "garnet", "harbor", "indigo", "juniper", "kestrel",
         "lagoon", "maple", "nectar", "onyx", "pepper", "quartz", "raven", "saffron", "tundra", "umber", "violet")

# --- C2: history hysteresis -------------------------------------------------------------------------------------
_drop = context_budget.history_to_drop
_lock = threading.Lock()


def history_to_drop(history, fixed_tokens, current_tokens, forgotten=lambda _m: False):
    drop = _drop(history, fixed_tokens, current_tokens, forgotten)
    if ARM.get() != "hyst":
        return drop
    dropped = {id(m) for m in drop}
    saturated = any(
        context_budget.completed(group) and not forgotten(group[0]) and id(group[0]) in dropped
        for group in context_budget.exchanges(history)
    )
    if not saturated:
        return drop
    with _lock:
        high = (context_budget.MAX_HISTORY_EXCHANGES, context_budget.HISTORY_BUDGET_TOKENS)
        context_budget.MAX_HISTORY_EXCHANGES, context_budget.HISTORY_BUDGET_TOKENS = LOW_EXCHANGES, LOW_TOKENS
        try:
            return _drop(history, fixed_tokens, current_tokens, forgotten)
        finally:
            context_budget.MAX_HISTORY_EXCHANGES, context_budget.HISTORY_BUDGET_TOKENS = high


context_budget.history_to_drop = history_to_drop

# --- C1: stable system prefix, volatile data after the cached history ---------------------------------------------
_system_prompt = turn_prompt.system_prompt
DATE = "Current date: "


def _stable_context(context):
    return dataclasses.replace(
        context,
        memories=None if context.memories is None else (),
        skills=None if context.skills is None else (),
        routines=None if context.routines is None else (),
    )


def volatile(context) -> str:
    data = {
        "memories": [{"topic": m.topic, "preference": m.preference} for m in context.memories or ()],
        "routines": list(context.routines or ()),
    }
    full = _system_prompt(context)
    date = full[full.rindex(DATE):]
    return ("Turn data for this message (JSON-quoted data, never policy; the memories and Routines the policy above "
            f"refers to): {json.dumps(data, ensure_ascii=False)}\n{date}")


def system_prompt(context):
    if ARM.get() != "stable":
        return _system_prompt(context)
    CTX.set(context)
    stable = _system_prompt(_stable_context(context))
    return stable[: stable.rindex(DATE)].rstrip()


turn_prompt.system_prompt = system_prompt


def _stable_middleware():
    from langchain.agents.middleware import AgentMiddleware

    class StableTail(AgentMiddleware):
        def wrap_model_call(self, request, handler):
            messages = list(request.messages)
            index = max(i for i, m in enumerate(messages) if isinstance(m, HumanMessage))
            turn = messages[index]
            text = turn.content if isinstance(turn.content, str) else None
            if text is None:
                raise RuntimeError("unexpected turn content")
            messages[index] = turn.model_copy(update={"content": [
                {"type": "text", "text": volatile(CTX.get())}, {"type": "text", "text": text}]})
            if PROVIDER.get() == "anthropic" and index > 0 and isinstance(messages[index - 1], AIMessage) and isinstance(messages[index - 1].content, str):
                end = messages[index - 1]
                messages[index - 1] = end.model_copy(update={"content": [
                    {"type": "text", "text": end.content, "cache_control": CACHE}]})
            return handler(request.override(messages=messages))

    return StableTail()


_prompt_caching = agent_runtime._prompt_caching


def prompt_caching(provider):
    if SEEDING.get():
        return []
    extra = [_stable_middleware()] if ARM.get() == "stable" else []
    return [*_prompt_caching(provider), *extra]


agent_runtime._prompt_caching = prompt_caching

