class Seeder:
    """The fake model that writes the seeded history: answers every seeded note with a short acknowledgement."""


def _fake_model():
    from langchain_core.language_models.fake_chat_models import FakeMessagesListChatModel

    class Fake(FakeMessagesListChatModel):
        def bind_tools(self, tools, **kwargs):
            return self

    return Fake(responses=[AIMessage(content="Noted.") for _ in range(10_000)])


class Factory:
    def __init__(self):
        self.real = provider_client.ProviderModelFactory()
        self.fake = _fake_model()

    def __call__(self, config):
        return self.fake if SEEDING.get() else self.real(config)


MEMORIES = tuple(team_memory.Memory(t, p) for t, p in (
    ("language", "Answer in short sentences."), ("units", "Use metric units."), ("dates", "Write dates as YYYY-MM-DD."),
    ("tone", "Be direct, no small talk."), ("lists", "Prefer bullet lists for several items."),
    ("tasks", "Task titles start with a capital letter."), ("weekends", "Never schedule anything on Sundays."),
    ("coffee", "I drink my coffee black."), ("music", "I like jazz."), ("city", "I live in Lisbon.")))
CHANGED = MEMORIES[:9] + (team_memory.Memory("city", "I moved to Porto."),)


def session(runtime, provider, stratum, arm, index, turns, seed):
    ARM.set(arm)
    rng = random.Random(f"{seed}/{stratum}/{index}")
    titles = [f"{rng.choice(WORDS).capitalize()} {rng.choice(WORDS)} {n}" for n in range(turns)]
    thread = f"eval:cache:{secrets.token_hex(8)}"
    records = []

    def ctx(memories):
        return agent_runtime.TurnContext(thread, "Eval Team", (TASKS,), provider, memories=memories, routines=(),
                                         routine_capacity=20_000, locale="en")

    if stratum == "sat":
        SEEDING.set(True)
        for k in range(context_budget.MAX_HISTORY_EXCHANGES):
            runtime.start(ctx(()), f"Note {k}: the {rng.choice(WORDS)} shelf holds box {rng.randint(10, 99)}.")
        SEEDING.set(False)
    for n in range(turns + 1):
        memories = (MEMORIES if n < 5 else CHANGED) if stratum == "mem" else ()
        probe = n == turns
        message = (f"What was the exact title of the task I asked you to create three messages ago? Answer with the title only."
                   if probe else f"Create a task titled '{titles[n]}'.")
        writes = []
        turn = ctx(memories)

        def run():
            result = runtime.start(turn, message)
            rounds = 0
            while result.status == "action-required" and rounds < 8:
                for request in result.actions:
                    if request.action == "create-task":
                        writes.append(dict(request.input))
                result = runtime.resume(turn, {r.interrupt_id: injection._result(injection.CASES[0], r, len(writes))
                                               for r in result.actions})
                rounds += 1
            return result

        try:
            result, counts = model_usage.measure(run)
            usage = eval_cost.Usage.of(counts)
            if probe:
                ok = result.status == "completed" and titles[turns - 3].casefold() in result.reply.casefold()
            else:
                ok = result.status == "completed" and len(writes) == 1 and titles[n].casefold() in str(writes[0].get("title", "")).casefold()
            status = result.status
        except Exception as exc:  # inconclusive
            cause = exc
            while cause.__cause__ is not None:
                cause = cause.__cause__
            print("error", stratum, arm, n, type(cause).__name__, str(cause)[:200], file=sys.stderr)
            usage, ok, status = eval_cost.Usage(unreported_calls=1), False, f"error:{type(exc).__name__}"
        records.append({"stratum": stratum, "arm": arm, "session": index, "turn": n, "probe": probe, "ok": ok,
                        "writes": len(writes), "titles": [str(w.get("title", "")) == titles[n] for w in writes] if not probe else [],
                        "status": status, "usage": usage.to_dict(),
                        "usd": eval_cost.cost(usage, provider.model).usd})
    return records


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--sessions", type=int, default=6); p.add_argument("--turns", type=int, default=10)
    p.add_argument("--cap", type=float, required=True); p.add_argument("--out", type=Path, required=True)
    p.add_argument("--seed", default="cache1"); p.add_argument("--workers", type=int, default=8)
    p.add_argument("--strata", default="sat,mem"); p.add_argument("--provider", default="openai")
    a = p.parse_args()
    ceiling = Ceiling(a.cap, 8_000); ceiling.install()
    keys = {"anthropic": "../.claude-key", "openai": "../.gpt-key"}
    model = {"anthropic": "claude-sonnet-5-5", "openai": "gpt-6-luna"}[a.provider]
    provider = agent_runtime.ProviderConfig(a.provider, model, _key(Path(keys[a.provider])), "low")
    PROVIDER.set(a.provider)
    runtime = agent_runtime.AgentRuntime(InMemorySaver(), model_factory=Factory())
    plan = {"sat": ("base", "hyst"), "mem": ("base", "stable")}
    jobs = []
    for stratum in a.strata.split(","):
        for index in range(a.sessions):
            for arm in eval_stats.arm_order(a.seed, a.provider, f"{stratum}/{index}", plan[stratum]):
                jobs.append((stratum, arm, index))
    records, lock = [], threading.Lock()

    def job(item):
        out = session(runtime, provider, *item, a.turns, a.seed)
        with lock:
            records.extend(out)

    with concurrent.futures.ThreadPoolExecutor(max_workers=a.workers) as pool:
        for f in [pool.submit(contextvars.copy_context().run, job, j) for j in jobs]:
            f.result()
    a.out.write_text(json.dumps({"records": records, "budget": ceiling.budget.summary(), "seed": a.seed}, indent=0))
    print(json.dumps(ceiling.budget.summary()))


main()

