"""Loopback stand-in for the OpenAI Responses endpoint: a fixed delay, then a tool call or a final reply."""
import json, sys, time, itertools
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

DELAY = float(sys.argv[2])
COUNTER = itertools.count()

def reply(body):
    n = next(COUNTER)
    items = body.get("input") or []
    last = items[-1] if items else {}
    tools = [t for t in body.get("tools") or [] if t.get("type") == "function" and t.get("name", "").startswith("a_")]
    usage = {"input_tokens": 3000, "output_tokens": 40, "total_tokens": 3040,
             "input_tokens_details": {"cached_tokens": 2048}, "output_tokens_details": {"reasoning_tokens": 0}}
    base = {"id": f"resp_{n}", "object": "response", "created_at": 0, "status": "completed", "model": body.get("model"),
            "parallel_tool_calls": True, "tool_choice": "auto", "tools": [], "usage": usage}
    if tools and last.get("type") != "function_call_output":
        return {**base, "output": [{"type": "function_call", "id": f"fc_{n}", "call_id": f"call_{n}",
                                    "name": tools[0]["name"], "arguments": json.dumps({"query": "notes"}), "status": "completed"}]}
    text = "Here is what I found in your notes. " * 8
    return {**base, "output": [{"type": "message", "id": f"msg_{n}", "status": "completed", "role": "assistant",
                                "content": [{"type": "output_text", "text": text, "annotations": []}]}]}

class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    def log_message(self, *a): pass
    def do_POST(self):
        body = json.loads(self.rfile.read(int(self.headers["content-length"])))
        time.sleep(DELAY)
        out = json.dumps(reply(body)).encode()
        self.send_response(200); self.send_header("content-type", "application/json")
        self.send_header("content-length", str(len(out))); self.end_headers(); self.wfile.write(out)

ThreadingHTTPServer(("127.0.0.1", int(sys.argv[1])), Handler).serve_forever()

