        original = turn_prompt.system_prompt

        def without(context):
            prompt = original(context)
            if ANCHOR + SENTENCE not in prompt:
                raise RuntimeError("shipped sentence missing")
            return prompt.replace(ANCHOR + SENTENCE, ANCHOR, 1)

        turn_prompt.system_prompt = without
        return
    if arm == "sent":
        original = turn_prompt.system_prompt

        def system_prompt(context):
            prompt = original(context)
            if ANCHOR not in prompt:
                raise RuntimeError("anchor missing")
            return prompt.replace(ANCHOR, ANCHOR + SENTENCE, 1)

        turn_prompt.system_prompt = system_prompt
        return
    raise SystemExit("unknown W4 arm")
